components.css:
.ds-button { min-height: 36px; padding-inline: 11px; border: 0; border-radius: 4px; font: 700 0.81rem 'Avenir Next', 'Segoe UI', sans-serif; cursor: pointer; }
.ds-button:focus-visible { outline: 2px solid var(--trace, #89e0da); outline-offset: 3px; }

.ds-range { display: inline-flex; gap: 3px; padding: 3px; border-radius: 6px; background: #1b3a4d; }
.ds-range .ds-button { background: transparent; color: var(--on-navy, #f2f8fb); }
.ds-range .ds-button:hover { background: #315568; }
.ds-range .ds-button[aria-pressed="true"] { color: var(--navy, #112c3d); background: var(--trace, #89e0da); }

.ds-button { min-height: 36px; padding-inline: 11px; border: 0; border-radius: 4px; font: 700 0.81rem 'Avenir Next', 'Segoe UI', sans-serif; cursor: pointer; }
.ds-button:focus-visible { outline: 2px solid var(--trace, #89e0da); outline-offset: 3px; }

.ds-retry { color: var(--navy, #112c3d); background: var(--trace, #89e0da); }
.ds-retry:hover { background: #b3ece8; }
.ds-retry:focus-visible { outline-color: var(--focus, #176c74); }

.ds-ledger { padding: 24px; background: var(--paper, #f8fafb); color: var(--ink, #162735); border: 1px solid var(--rule, #cdd9e0); border-radius: 14px; font-family: 'Avenir Next', 'Segoe UI', sans-serif; }
.ds-ledger h2 { margin: 0; font: 700 1.4rem/1.2 var(--heading-font, sans-serif); }
.ds-ledger dl { margin: 20px 0 0; border-top: 1px solid var(--rule, #cdd9e0); }
.ds-ledger dl div { display: flex; justify-content: space-between; gap: 10px; padding-block: 16px; border-bottom: 1px solid var(--rule, #cdd9e0); }
.ds-ledger dt, .ds-ledger dd { color: var(--muted, #4d6170); font-size: 0.81rem; margin: 0; }

.ds-chart { padding: 25px 27px 20px; border-radius: 14px; background: var(--navy, #112c3d); color: var(--on-navy, #f2f8fb); font-family: 'Avenir Next', 'Segoe UI', sans-serif; }
.ds-chart h2 { margin: 0; font: 700 1.4rem/1.2 var(--heading-font, sans-serif); }
.ds-chart p { margin: 4px 0 0; font-size: 0.81rem; color: var(--on-navy-muted, #aec3ce); }
.ds-chart-state { min-height: 165px; display: grid; place-items: center; color: var(--on-navy-muted, #aec3ce); }
